/* Admin Panel JS — sidebar toggle, modals, tooltips */

(function () {
  'use strict';

  /* ── Sidebar Toggle ── */
  var sidebar = document.getElementById('sidebar');
  var toggle  = document.getElementById('sidebarToggle');

  if (toggle && sidebar) {
    toggle.addEventListener('click', function () {
      sidebar.classList.toggle('open');
    });

    // Close sidebar on outside click (mobile)
    document.addEventListener('click', function (e) {
      if (window.innerWidth <= 768 &&
          sidebar.classList.contains('open') &&
          !sidebar.contains(e.target) &&
          !toggle.contains(e.target)) {
        sidebar.classList.remove('open');
      }
    });
  }

  /* ── Tabs ── */
  document.querySelectorAll('.tab').forEach(function (tab) {
    tab.addEventListener('click', function () {
      var group  = tab.dataset.tabGroup;
      var target = tab.dataset.tab;

      if (!group || !target) return;

      // Activate tab button
      document.querySelectorAll('.tab[data-tab-group="' + group + '"]').forEach(function (t) {
        t.classList.remove('active');
      });
      tab.classList.add('active');

      // Show corresponding panel
      document.querySelectorAll('.tab-panel[data-tab-group="' + group + '"]').forEach(function (p) {
        p.classList.add('hidden');
      });
      var panel = document.querySelector('.tab-panel[data-tab-group="' + group + '"][data-tab="' + target + '"]');
      if (panel) panel.classList.remove('hidden');
    });
  });

  /* ── Modals ── */
  document.querySelectorAll('[data-modal]').forEach(function (trigger) {
    trigger.addEventListener('click', function () {
      var id = trigger.dataset.modal;
      var modal = document.getElementById(id);
      if (modal) {
        modal.classList.remove('hidden');
        document.body.style.overflow = 'hidden';
      }
    });
  });

  document.querySelectorAll('[data-modal-close]').forEach(function (closeBtn) {
    closeBtn.addEventListener('click', function () {
      var overlay = closeBtn.closest('.modal-overlay');
      if (overlay) {
        overlay.classList.add('hidden');
        document.body.style.overflow = '';
      }
    });
  });

  // Close modal on overlay click
  document.querySelectorAll('.modal-overlay').forEach(function (overlay) {
    overlay.addEventListener('click', function (e) {
      if (e.target === overlay) {
        overlay.classList.add('hidden');
        document.body.style.overflow = '';
      }
    });
  });

  // Close modal on Escape key
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      document.querySelectorAll('.modal-overlay:not(.hidden)').forEach(function (m) {
        m.classList.add('hidden');
        document.body.style.overflow = '';
      });
    }
  });

  /* ── Table Row Selection ── */
  document.querySelectorAll('.table-wrapper').forEach(function (wrapper) {
    var checkboxes = wrapper.querySelectorAll('tbody input[type="checkbox"]');
    var selectAll  = wrapper.querySelector('thead input[type="checkbox"]');

    if (selectAll) {
      selectAll.addEventListener('change', function () {
        checkboxes.forEach(function (cb) { cb.checked = selectAll.checked; });
        updateBulkActions(wrapper);
      });
    }

    checkboxes.forEach(function (cb) {
      cb.addEventListener('change', function () {
        updateBulkActions(wrapper);
      });
    });
  });

  function updateBulkActions(wrapper) {
    var checked = wrapper.querySelectorAll('tbody input[type="checkbox"]:checked').length;
    var bulkBar = document.querySelector('.bulk-action-bar');
    var countEl = document.querySelector('.bulk-count');
    if (bulkBar) {
      bulkBar.classList.toggle('hidden', checked === 0);
    }
    if (countEl) {
      countEl.textContent = checked;
    }
  }

  /* ── Toast / Flash dismiss ── */
  document.querySelectorAll('.alert[data-auto-dismiss]').forEach(function (alert) {
    setTimeout(function () {
      var bs = new bootstrap.Alert(alert); // if bootstrap available, otherwise just hide
      alert.style.transition = 'opacity .4s';
      alert.style.opacity = '0';
      setTimeout(function () { alert.remove(); }, 400);
    }, 5000);
  });

})();
